import re

def solve(env, goal):
    def base_name(s):
        return re.sub(r"\s+\d+$", "", s.strip().lower())

    def items_in(obs):
        """Return list of (item_full, receptacle_or_None) from observation text."""
        out = []
        for line in obs.splitlines():
            m = re.search(r"On the (.+?), you see (.+?)\.", line)
            if m:
                rec = m.group(1).strip()
                for pm in re.finditer(r"(?:a |an )?([a-z]+(?:\s+\d+)?)", m.group(2)):
                    out.append((pm.group(1), rec))
                continue
            m = re.search(r"In it, you see (.+?)\.", line)
            if m:
                for pm in re.finditer(r"(?:a |an )?([a-z]+(?:\s+\d+)?)", m.group(1)):
                    out.append((pm.group(1), None))
                continue
        return out

    def receptacles_in(obs):
        """Return list of receptacle names from room description or look feedback."""
        recs = []
        for pm in re.finditer(r"(?:a |an )([a-z]+(?:\s+\d+)?)", obs):
            recs.append(pm.group(1))
        # dedupe preserving order
        seen = set()
        uniq = []
        for r in recs:
            if r not in seen:
                seen.add(r)
                uniq.append(r)
        return uniq

    def find_matching(obs, name):
        res = []
        for it, rec in items_in(obs):
            if base_name(it) == name:
                res.append((it, rec))
        return res

    def carrying(obs):
        m = re.search(r"carrying (?:a |an )?([a-z]+(?:\s+\d+)?)", obs, re.I)
        if m:
            return m.group(1)
        return None

    def is_closed_feedback(fb):
        return "is closed" in fb.lower()

    # Parse goal
    m = re.search(r"examine (?:the )?([a-z]+(?:\s+\d+)?) with (?:the )?([a-z]+(?:\s+\d+)?)", goal, re.I)
    if m:
        obj_type = base_name(m.group(1))
        lamp_type = base_name(m.group(2))
    else:
        obj_type = "pillow"
        lamp_type = "desklamp"

    # Initial room description
    room_desc = env.observation
    receptacles = receptacles_in(room_desc)
    visited = set()

    def go(cmd):
        return env.step(cmd)

    def ensure_open(rec):
        fb = go("go to " + rec)
        if is_closed_feedback(fb):
            go("open " + rec)
            fb = env.observation
        return fb

    def take_item(item, rec):
        fb = go("take " + item + " from " + rec)
        return fb

    # Check if already carrying object
    inv_obs = go("inventory")
    cur = carrying(inv_obs)
    holding = False
    obj_full = None
    if cur and base_name(cur) == obj_type:
        holding = True
        obj_full = cur

    # Find object
    if not holding:
        # First check current observation
        obs = env.observation
        found = find_matching(obs, obj_type)
        if found:
            item, rec = found[0]
            if rec:
                ensure_open(rec)
            take_item(item, rec)
            obj_full = item
            holding = True
        else:
            # Search receptacles
            for rec in list(receptacles):
                if rec in visited:
                    continue
                visited.add(rec)
                fb = ensure_open(rec)
                obs = env.observation
                found = find_matching(obs, obj_type)
                if found:
                    item, _ = found[0]
                    take_item(item, rec)
                    obj_full = item
                    holding = True
                    break
            if not holding:
                # look to discover more receptacles
                obs = go("look")
                more = receptacles_in(obs)
                for rec in more:
                    if rec in visited:
                        continue
                    visited.add(rec)
                    fb = ensure_open(rec)
                    obs = env.observation
                    found = find_matching(obs, obj_type)
                    if found:
                        item, _ = found[0]
                        take_item(item, rec)
                        obj_full = item
                        holding = True
                        break
                receptacles.extend([r for r in more if r not in receptacles])

    # Find lamp
    lamp_full = None
    lamp_rec = None
    obs = env.observation
    found = find_matching(obs, lamp_type)
    if found:
        lamp_full, lamp_rec = found[0]
    else:
        for rec in list(receptacles):
            fb = go("go to " + rec)
            if is_closed_feedback(fb):
                go("open " + rec)
            obs = env.observation
            found = find_matching(obs, lamp_type)
            if found:
                lamp_full, lamp_rec = found[0]
                break
        if not lamp_full:
            obs = go("look")
            more = receptacles_in(obs)
            for rec in more:
                fb = go("go to " + rec)
                if is_closed_feedback(fb):
                    go("open " + rec)
                obs = env.observation
                found = find_matching(obs, lamp_type)
                if found:
                    lamp_full, lamp_rec = found[0]
                    break
                receptacles.append(rec) if rec not in receptacles else None

    # Go to lamp
    if lamp_full:
        # Ensure at lamp's receptacle
        obs = env.observation
        found = find_matching(obs, lamp_type)
        if not found:
            if lamp_rec:
                fb = go("go to " + lamp_rec)
                if is_closed_feedback(fb):
                    go("open " + lamp_rec)
            else:
                for rec in list(receptacles):
                    fb = go("go to " + rec)
                    obs = env.observation
                    if find_matching(obs, lamp_type):
                        break
        go("use " + lamp_full)

    # If not holding object, try to obtain it now
    if not holding:
        obs = env.observation
        found = find_matching(obs, obj_type)
        if found:
            item, rec = found[0]
            take_item(item, rec)
            obj_full = item
            holding = True
        else:
            for rec in list(receptacles):
                fb = ensure_open(rec)
                obs = env.observation
                found = find_matching(obs, obj_type)
                if found:
                    item, _ = found[0]
                    take_item(item, rec)
                    obj_full = item
                    holding = True
                    break

    # Ensure lamp is on
    if lamp_full:
        obs = env.observation
        found = find_matching(obs, lamp_type)
        if not found:
            # go back to lamp
            for rec in list(receptacles):
                fb = go("go to " + rec)
                obs = env.observation
                if find_matching(obs, lamp_type):
                    break
        go("use " + lamp_full)

    # Examine
    if holding and obj_full:
        go("examine " + obj_full)

    return None

import re


def solve(env, goal):
    goal_l = goal.lower()
    m = re.search(r"examine (?:the |a |an )?(.+?) (?:with|under|using) (?:the |a |an )?(.+?)(?:[.!]|$)", goal_l)
    if m:
        obj_type = m.group(1).strip()
        lamp_type = m.group(2).strip()
    else:
        obj_type = "pencil"
        lamp_type = "lamp"
    obj_type = re.sub(r"^(?:a |an |the )", "", obj_type).rstrip(".!")
    lamp_type = re.sub(r"^(?:a |an |the )", "", lamp_type).rstrip(".!")

    def norm(t):
        t = t.lower()
        t = re.sub(r"^(?:a |an |the )", "", t)
        return t.rstrip(".!")

    obj_type = norm(obj_type)
    lamp_type = norm(lamp_type)

    def is_obj(name):
        n = norm(name)
        if n == obj_type:
            return True
        if n.rstrip("s") == obj_type.rstrip("s"):
            return True
        return False

    def is_lamp(name):
        n = norm(name)
        if n == lamp_type:
            return True
        if "lamp" in n and "lamp" in lamp_type:
            if lamp_type == "lamp":
                return True
            return lamp_type in n or n in lamp_type
        return False

    def parse_items(text):
        items = []
        # match "a NAME NUM" optionally separated by commas/and
        for im in re.finditer(r"\ba ([a-z]+) (\d+)", text):
            items.append((im.group(1).lower(), im.group(2)))
        return items

    def current_loc(text):
        # "You arrive at X." or "On the X, you see"
        mm = re.search(r"You arrive at ([^.\n]+?)\.", text)
        if mm:
            return mm.group(1).strip().lower()
        mm = re.search(r"On the ([^,\n]+?), you see", text)
        if mm:
            return mm.group(1).strip().lower()
        mm = re.search(r"In it, you see", text)
        if mm:
            return None
        return None

    def is_closed(text):
        return "is closed" in text.lower()

    def is_open(text):
        return "is open" in text.lower()

    def take(name, num, loc):
        return env.step("take %s %s from %s" % (name, num, loc))

    def go(loc):
        return env.step("go to " + loc)

    def open_rec(loc):
        return env.step("open " + loc)

    def use(name, num):
        return env.step("use %s %s" % (name, num))

    # Get receptacles from initial room description
    room = env.observation
    receptacles = []
    seen_loc = set()
    for mm in re.finditer(r"a ([a-z]+) (\d+)", room):
        name = mm.group(1).lower()
        num = mm.group(2)
        loc = name + " " + num
        if loc not in seen_loc:
            seen_loc.add(loc)
            receptacles.append((name, num))

    # Also include objects in room that might be receptacles? We scan all listed.
    # But if room text is empty (after first look), we may need to use initial observation.
    # We already captured from env.observation which is room description at start.

    found_obj = None
    found_lamp = None

    def scan_loc(locname):
        nonlocal found_obj, found_lamp
        go(locname)
        txt = env.observation
        if is_closed(txt):
            open_rec(locname)
            txt = env.observation
        items = parse_items(txt)
        loc = current_loc(txt) or locname
        for name, num in items:
            if found_obj is None and is_obj(name):
                found_obj = (loc, name, num)
            if found_lamp is None and is_lamp(name):
                found_lamp = (loc, name, num)

    # First pass: visit all receptacles, opening closed ones
    visited = set()
    for name, num in receptacles:
        loc = name + " " + num
        if loc in visited:
            continue
        visited.add(loc)
        scan_loc(loc)
        if found_obj is not None and found_lamp is not None:
            break

    # If object not found, try going to each again and looking more carefully
    if found_obj is None:
        for name, num in receptacles:
            loc = name + " " + num
            go(loc)
            txt = env.observation
            if is_closed(txt):
                open_rec(loc)
                txt = env.observation
            items = parse_items(txt)
            for iname, inum in items:
                if is_obj(iname):
                    found_obj = (current_loc(txt) or loc, iname, inum)
                    break
            if found_obj:
                break

    # If lamp not found, scan for any lamp
    if found_lamp is None:
        for name, num in receptacles:
            loc = name + " " + num
            go(loc)
            txt = env.observation
            if is_closed(txt):
                open_rec(loc)
                txt = env.observation
            items = parse_items(txt)
            for iname, inum in items:
                if "lamp" in iname.lower():
                    found_lamp = (current_loc(txt) or loc, iname, inum)
                    break
            if found_lamp:
                break

    if found_obj is None:
        return

    # Take the object
    loc, name, num = found_obj
    go(loc)
    txt = env.observation
    if is_closed(txt):
        open_rec(loc)
    res = take(name, num, loc)
    if "nothing happens" in res.lower():
        open_rec(loc)
        res = take(name, num, loc)

    # Use the lamp
    if found_lamp is not None:
        lloc, lname, lnum = found_lamp
        go(lloc)
        txt = env.observation
        if is_closed(txt):
            open_rec(lloc)
        use(lname, lnum)
    else:
        # Try using any lamp in inventory? Not possible; try examining held object? 
        # Fallback: go to dresser or desk and use any lamp found there.
        pass

    return

import re

def solve(env, goal):
    g = goal.lower()
    m = re.match(r'put a clean (\w+) (?:in|on) (?:a |the )?(\w+)', g)
    if not m:
        m = re.match(r'put a clean (\w+) (?:in|on) (\w+)', g)
    if m:
        obj_type, rec_type = m.group(1), m.group(2)
    else:
        words = re.findall(r'\b[a-z]+\b', g)
        obj_type = None
        rec_type = words[-1] if words else None
        for i, w in enumerate(words):
            if w == 'clean' and i + 1 < len(words):
                obj_type = words[i + 1]
                break

    def norm(s):
        return s.strip().lower()

    def base(name):
        return norm(name).split()[0]

    def obj_matches(name, typ):
        return base(name) == typ

    def rec_matches(name, typ):
        return base(name) == typ

    def step(cmd):
        return env.step(cmd)

    def obs():
        return env.observation

    def inv():
        r = step('inventory')
        m = re.search(r'carrying: (.*?)\.', r, re.I)
        if not m:
            m = re.search(r'carrying (.*?)\.', r, re.I)
        if not m:
            return []
        part = m.group(1)
        if 'nothing' in part.lower():
            return []
        return [norm(o) for o in re.findall(r'([a-z]+(?:\s+\d+)?)', part)]

    def held_obj():
        for h in inv():
            if obj_matches(h, obj_type):
                return h
        return None

    def is_closed_here(o):
        return bool(re.search(r'is closed|it is closed', o, re.I))

    def open_here(name):
        o = obs()
        if is_closed_here(o):
            step('open ' + name)

    # Extract receptacle candidates from initial observation.
    obs0 = obs()
    all_tokens = re.findall(r'([a-z]+(?:\s+\d+)?)', obs0)
    receptacles = []
    seen = set()
    for t in all_tokens:
        t = norm(t)
        if re.search(r'\d+', t) and t not in seen:
            seen.add(t)
            receptacles.append(t)

    # Find object: scan receptacles (open if closed).
    target_obj = None
    target_rec = None

    h = held_obj()
    if h:
        target_obj = h

    if target_obj is None:
        for rec in receptacles:
            if rec_matches(rec, obj_type):
                continue
            step('go to ' + rec)
            open_here(rec)
            o = obs()
            mo = re.search(r'you see (.*?)\.', o, re.I)
            if mo and 'nothing' not in mo.group(1).lower():
                for tok in re.findall(r'([a-z]+(?:\s+\d+)?)', mo.group(1)):
                    tok = norm(tok)
                    if obj_matches(tok, obj_type):
                        target_obj = tok
                        target_rec = rec
                        break
            if target_obj:
                break

    if target_obj is None:
        return

    # Take if not held.
    if held_obj() is None:
        if target_rec:
            step('go to ' + target_rec)
            open_here(target_rec)
            step('take ' + target_obj + ' from ' + target_rec)

    # Clean with sink basin.
    sink = None
    for rec in receptacles:
        if rec_matches(rec, 'sinkbasin'):
            sink = rec
            break
    if sink is None:
        # fallback: search observation text
        for t in re.findall(r'([a-z]+(?:\s+\d+)?)', obs()):
            if rec_matches(t, 'sinkbasin'):
                sink = norm(t)
                break
    if sink:
        step('go to ' + sink)
        h = held_obj()
        if h:
            step('clean ' + h + ' with ' + sink)

    # Find destination.
    dest = None
    for rec in receptacles:
        if rec_matches(rec, rec_type):
            dest = rec
            break
    if dest is None:
        for t in re.findall(r'([a-z]+(?:\s+\d+)?)', obs()):
            if rec_matches(t, rec_type):
                dest = norm(t)
                break

    if dest:
        step('go to ' + dest)
        open_here(dest)
        h = held_obj()
        if h:
            step('move ' + h + ' to ' + dest)

    return

import re

def solve(env, goal):
    goal_lower = goal.lower()

    # --- Parse goal ---
    # target object: word after "clean" (ignoring articles), or after put/place/move
    target = None
    m = re.search(r'clean\s+(?:some|a|an|the)?\s*([a-z]+)', goal_lower)
    if m:
        target = m.group(1)
    else:
        m = re.search(r'(?:put|place|move)\s+(?:some|a|an|the)?\s*([a-z]+)', goal_lower)
        if m:
            target = m.group(1)

    # destination: word after last in/to/on/into (ignoring articles)
    dest = None
    for m in re.finditer(r'\b(?:in|to|on|into)\s+(?:the\s+)?([a-z]+)', goal_lower):
        cand = m.group(1)
        if cand != target:
            dest = cand
    if dest is None:
        dest = "shelf"

    def norm(s):
        return re.sub(r'^(a|an|the)\s+', '', s.strip()) if s else s

    target = norm(target)
    dest = norm(dest)

    obs = env.observation
    room_recs = re.findall(r'\b([a-z]+ \d+)\b', obs.lower())
    seen = set()
    room_recs = [r for r in dict.fromkeys(room_recs) if r not in seen]

    knowledge = {}   # rec -> list of object names (None means unknown)
    opened = set()
    current = None

    def parse_obs(text):
        tl = text.lower()
        # "You arrive at X." sets current, but we set it ourselves
        m = re.search(r'(?:on|in) the ([a-z]+ \d+), you (?:see|find)([^.]*)', tl)
        if m:
            rec = m.group(1)
            items = re.findall(r'\b([a-z]+ \d+)\b', m.group(2))
            knowledge[rec] = items
            return
        m = re.search(r'in it, you see([^.]*)', tl)
        if m and current:
            items = re.findall(r'\b([a-z]+ \d+)\b', m.group(1))
            knowledge[current] = items
            return
        if 'you see nothing' in tl:
            if current:
                knowledge[current] = []
            return

    def is_target(obj):
        # obj like "plate 2"; target like "plate"
        return obj.split()[0] == target

    def find_target():
        # prefer plates over other objects; return (rec, obj)
        for rec, items in knowledge.items():
            if items is None:
                continue
            for it in items:
                if is_target(it):
                    return rec, it
        return None, None

    def is_dest(rec):
        return rec.split()[0] == dest

    def go(loc):
        nonlocal current
        r = env.step("go to " + loc)
        current = loc
        parse_obs(r)
        return r

    def ensure_open(rec):
        if rec in opened:
            return
        r = env.step("open " + rec)
        if r.lower().startswith("you open") or "you open" in r.lower():
            opened.add(rec)
        parse_obs(r)

    def look():
        r = env.step("look")
        parse_obs(r)
        return r

    # --- Phase 1: find target ---
    # Only need to explore until we find a target. But to be safe and cheap,
    # explore containers first (they often hold plates), then open surfaces.
    containers = [r for r in room_recs if r.split()[0] in ('fridge','microwave','cabinet','drawer')]
    others = [r for r in room_recs if r not in containers]

    found_rec, found_obj = find_target()

    # First pass: containers (open them)
    for rec in containers:
        if found_obj is not None:
            break
        if current != rec:
            go(rec)
        ensure_open(rec)
        found_rec, found_obj = find_target()

    # Second pass: open surfaces
    if found_obj is None:
        for rec in others:
            if found_obj is not None:
                break
            if current != rec:
                go(rec)
            # we don't know contents yet; parse from arrival
            if knowledge.get(rec) is None:
                look()
            found_rec, found_obj = find_target()

    # Third pass: if still nothing, try looking everywhere (surfaces we skipped)
    if found_obj is None:
        for rec in room_recs:
            if found_obj is not None:
                break
            if current != rec:
                go(rec)
            if rec.split()[0] in ('fridge','microwave','cabinet','drawer'):
                ensure_open(rec)
            if knowledge.get(rec) is None:
                look()
            found_rec, found_obj = find_target()

    if found_obj is None:
        return

    # --- Phase 2: take it ---
    if current != found_rec:
        go(found_rec)
    if found_rec.split()[0] in ('fridge','microwave','cabinet','drawer'):
        ensure_open(found_rec)
    r = env.step(f"take {found_obj} from {found_rec}")
    holding = found_obj if ("pick up" in r.lower() or "you pick" in r.lower()) else None

    # --- Phase 3: clean ---
    if holding:
        sink = None
        for rec in room_recs:
            if rec.split()[0] == 'sinkbasin':
                sink = rec
                break
        if sink is None:
            sink = 'sinkbasin 1'
        if current != sink:
            go(sink)
        r = env.step(f"clean {holding} with {sink}")
        parse_obs(r)

    # --- Phase 4: move to destination ---
    if holding:
        dst = None
        for rec in room_recs:
            if is_dest(rec):
                dst = rec
                break
        if dst is None:
            # fallback: any rec whose name starts with dest
            for rec in room_recs:
                if rec.split()[0].startswith(dest):
                    dst = rec
                    break
        if dst is None:
            dst = dest + " 1"
        if current != dst:
            go(dst)
        env.step(f"move {holding} to {dst}")

import re

def solve(env, goal):
    def norm(s):
        return re.sub(r"\s+", " ", s.lower().strip())

    def parse_goal(g):
        g = norm(g)
        obj = None
        dest = None
        m = re.search(r"heat\s+(?:some\s+|a\s+|an\s+)?([a-z]+)", g)
        if m:
            obj = m.group(1)
        if obj is None:
            m = re.search(r"(?:put|place|move)\s+(?:some\s+|a\s+|an\s+)?([a-z]+)", g)
            if m:
                obj = m.group(1)
        m = re.search(r"(?:in|on|into|to)\s+(?:the\s+|a\s+|an\s+)?([a-z]+)", g)
        if m:
            dest = m.group(1)
        return obj, dest

    def find_type_in_text(text, typ):
        res = []
        for m in re.finditer(r"\b([a-z]+) (\d+)\b", text):
            if m.group(1) == typ:
                res.append(m.group(0))
        return res

    def extract_receptacles(text):
        res = []
        for m in re.finditer(r"\b([a-z]+) (\d+)\b", text):
            res.append(m.group(0))
        return res

    def is_closed(obs, place):
        return ("The " + place + " is closed") in obs or (place + " is closed") in obs

    def is_open(obs, place):
        return ("The " + place + " is open") in obs or (place + " is open") in obs

    def go_to(place):
        return env.step("go to " + place)

    def open_place(place):
        return env.step("open " + place)

    def take(obj, place):
        return env.step("take " + obj + " from " + place)

    def move(obj, place):
        return env.step("move " + obj + " to " + place)

    target_obj, target_dest = parse_goal(goal)

    # Get initial room description for receptacles
    room_obs = env.observation
    receptacles = extract_receptacles(room_obs)

    # dedupe preserving order
    seen = set()
    places = []
    for p in receptacles:
        if p not in seen:
            seen.add(p)
            places.append(p)

    # Find microwave early (cheap)
    microwave = None
    for p in places:
        if p.lower().startswith("microwave"):
            microwave = p
            break

    # Find destination early
    dest_place = None
    for p in places:
        if target_dest and p.lower().startswith(target_dest):
            dest_place = p
            break

    # Find object: prioritize likely surfaces (countertop) but also open containers.
    # We'll do a careful search with a limited number of places to avoid budget.
    # Strategy: first scan open surfaces (countertop, sinkbasin, stoveburner, coffeemachine, toaster, garbagecan)
    # Then scan closable containers (cabinet, drawer, fridge) but stop as soon as found.
    priority_keywords = ["countertop", "sinkbasin", "stoveburner", "coffeemachine", "toaster", "garbagecan"]
    secondary_keywords = ["fridge", "cabinet", "drawer"]

    found_obj = None
    found_obj_place = None

    def scan_places(place_list):
        nonlocal found_obj, found_obj_place
        for place in place_list:
            if found_obj is not None:
                return
            obs = go_to(place)
            # open if closed
            if is_closed(obs, place):
                obs = open_place(place)
            hits = find_type_in_text(obs, target_obj)
            if hits:
                found_obj = hits[0]
                found_obj_place = place
                return

    # First scan priority places
    priority = [p for p in places if any(p.lower().startswith(k) for k in priority_keywords)]
    scan_places(priority)

    # If not found, scan secondary places
    if found_obj is None:
        secondary = [p for p in places if any(p.lower().startswith(k) for k in secondary_keywords)]
        scan_places(secondary)

    # If still not found, scan remaining places
    if found_obj is None:
        remaining = [p for p in places if p not in priority and p not in secondary]
        scan_places(remaining)

    # Now take the object
    if found_obj and found_obj_place:
        obs = go_to(found_obj_place)
        if is_closed(obs, found_obj_place):
            obs = open_place(found_obj_place)
        take(found_obj, found_obj_place)

    # Heat with microwave
    if found_obj and microwave:
        obs = go_to(microwave)
        if is_closed(obs, microwave):
            obs = open_place(microwave)
        env.step("heat " + found_obj + " with " + microwave)

    # Move to destination
    if found_obj and dest_place:
        obs = go_to(dest_place)
        if is_closed(obs, dest_place):
            obs = open_place(dest_place)
        move(found_obj, dest_place)

    return

import re

def solve(env, goal):
    def obj_type(name):
        return re.sub(r'\s+\d+$', '', name.strip().lower())

    def parse_pairs(text):
        return [(n.lower(), num) for n, num in re.findall(r'\b([a-zA-Z]+)\s+(\d+)\b', text)]

    def containers():
        return {'drawer', 'cabinet', 'fridge', 'microwave', 'safe', 'box'}

    def is_container(name):
        return name in containers()

    def visible_objects(obs):
        objs = []
        for seg in re.findall(r'you see([^\n]*)', obs, re.I):
            for name, num in parse_pairs(seg):
                if name not in ('the', 'a', 'an', 'it', 'you', 'nothing', 'and'):
                    objs.append((name, num))
        return objs

    def held_objects():
        inv = env.step("inventory")
        objs = []
        for name, num in parse_pairs(inv):
            if name not in ('the', 'a', 'an', 'you', 'are', 'carrying', 'nothing'):
                objs.append((name, num))
        return objs

    def go(name, num):
        return env.step(f"go to {name} {num}")

    def open_rec(name, num):
        return env.step(f"open {name} {num}")

    def close_rec(name, num):
        return env.step(f"close {name} {num}")

    def take(obj, rec):
        return env.step(f"take {obj} from {rec}")

    def move(obj, rec):
        return env.step(f"move {obj} to {rec}")

    def heat(obj, rec):
        return env.step(f"heat {obj} with {rec}")

    goal_lower = goal.lower()

    # determine target object type: the thing to heat
    target_obj = None
    m = re.search(r'heat\s+(?:some\s+|a\s+|an\s+|the\s+)?(\w+)', goal_lower)
    if m:
        target_obj = m.group(1)
    else:
        m = re.search(r'(?:heat|warm)\s+(?:some\s+|a\s+|an\s+)?(\w+)', goal_lower)
        if m:
            target_obj = m.group(1)

    # determine destination receptacle type
    dest = None
    # look after "in", "on", "to" (not the target object)
    for m in re.finditer(r'\b(?:in|on|to)\s+(?:the\s+|a\s+|an\s+)?(\w+)', goal_lower):
        cand = m.group(1)
        if cand not in ('the', 'a', 'an') and cand != target_obj:
            dest = cand
            break
    if dest is None:
        m = re.search(r'put\s+.*?\b(?:in|on|to)\s+(?:the\s+|a\s+|an\s+)?(\w+)', goal_lower)
        if m:
            dest = m.group(1)

    # Parse room description for known receptacles
    room = env.observation
    known_recs = []
    seen = set()
    for name, num in parse_pairs(room):
        if name in ('you', 'are', 'in', 'the', 'middle', 'of', 'room', 'looking', 'quickly', 'around', 'see'):
            continue
        key = (name, num)
        if key not in seen:
            seen.add(key)
            known_recs.append((name, num))

    # Locate microwave
    microwave = None
    for name, num in known_recs:
        if name == 'microwave':
            microwave = (name, num)
            break

    def find_object():
        # Check inventory first
        for name, num in held_objects():
            if obj_type(name) == target_obj:
                return (name, num, None)
        # check current location
        obs = env.observation
        for name, num in visible_objects(obs):
            if obj_type(name) == target_obj:
                # need location; use last go target unknown, so fall through to systematic search
                pass
        # systematic search
        for name, num in known_recs:
            go(name, num)
            obs = env.observation
            if is_container(name) and 'closed' in obs.lower():
                open_rec(name, num)
                obs = env.observation
            for oname, onum in visible_objects(obs):
                if obj_type(oname) == target_obj:
                    return (oname, onum, (name, num))
        return None

    found = find_object()
    if not found:
        return
    oname, onum, loc = found

    # if not held, take it
    held = held_objects()
    if not any(obj_type(n) == target_obj for n, _ in held):
        if loc:
            go(loc[0], loc[1])
            obs = env.observation
            if is_container(loc[0]) and 'closed' in obs.lower():
                open_rec(loc[0], loc[1])
            take(f"{oname} {onum}", f"{loc[0]} {loc[1]}")
        else:
            # it's already held
            pass

    # heat with microwave
    if microwave is None:
        # try to find microwave in current observation
        for name, num in parse_pairs(env.observation):
            if name == 'microwave':
                microwave = (name, num)
                break
    if microwave is None:
        for name, num in known_recs:
            if name == 'microwave':
                microwave = (name, num)
                break
    if microwave:
        go(microwave[0], microwave[1])
        obs = env.observation
        if 'closed' in obs.lower():
            open_rec(microwave[0], microwave[1])
        # identify held target
        held = held_objects()
        held_target = None
        for n, num in held:
            if obj_type(n) == target_obj:
                held_target = f"{n} {num}"
                break
        if held_target:
            heat(held_target, f"{microwave[0]} {microwave[1]}")

    # find destination receptacle
    dest_rec = None
    for name, num in known_recs:
        if name == dest:
            dest_rec = (name, num)
            break
    if dest_rec is None:
        for name, num in parse_pairs(env.observation):
            if name == dest:
                dest_rec = (name, num)
                break

    if dest_rec:
        go(dest_rec[0], dest_rec[1])
        obs = env.observation
        if is_container(dest_rec[0]) and 'closed' in obs.lower():
            open_rec(dest_rec[0], dest_rec[1])
        held = held_objects()
        held_target = None
        for n, num in held:
            if obj_type(n) == target_obj:
                held_target = f"{n} {num}"
                break
        if held_target:
            move(held_target, f"{dest_rec[0]} {dest_rec[1]}")
        if is_container(dest_rec[0]):
            close_rec(dest_rec[0], dest_rec[1])
